"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { SearchForm } from "@/components/SearchForm";
import { ResultCard } from "@/components/ResultCard/ResultCard";
import { SavedTripsPanel } from "@/components/SavedTripsPanel/SavedTripsPanel";
import { tripFingerprint } from "@/lib/matchSavedFlight";
import { loadSavedTrips, removeSavedTrip, upsertSavedTrip } from "@/lib/savedTripsStorage";
import type { FlightResult, SearchParams } from "@/types";
import type { SavedTrip } from "@/types/savedTrip";

type StopFilter = "all" | "direct" | "oneStop" | "twoPlusStops";

type SortBy = "price" | "durationShortest";
type SearchApiResponse =
  | FlightResult[]
  | {
      results: FlightResult[];
      meta?: {
        stage?: "fast" | "full";
        hasMore?: boolean;
        flexDaysUsed?: 0 | 1 | 3 | 5 | 7;
        cacheHit?: boolean;
        timingsMs?: {
          total?: number;
          serp?: number;
          duffel?: number;
          amadeus?: number;
          travelpayouts?: number;
          enrich?: number;
        };
      };
    };

type SearchApiMeta =
  | {
      stage?: "fast" | "full";
      hasMore?: boolean;
      flexDaysUsed?: 0 | 1 | 3 | 5 | 7;
      cacheHit?: boolean;
      timingsMs?: {
        total?: number;
        serp?: number;
        duffel?: number;
        amadeus?: number;
        travelpayouts?: number;
        enrich?: number;
      };
    }
  | undefined;

function normalizeSearchResponse(data: SearchApiResponse): {
  results: FlightResult[];
  meta: SearchApiMeta;
} {
  if (Array.isArray(data)) {
    return { results: data, meta: undefined };
  }
  return { results: data.results, meta: data.meta };
}

function resultIdentity(r: FlightResult): string {
  return [
    r.originAirportCode,
    r.airportCode,
    r.departureDate,
    r.returnDate ?? "",
    r.airlineIataCode ?? r.airline,
    String(r.price),
    String(r.stops),
  ].join("|");
}

function mergeUniqueResults(base: FlightResult[], incoming: FlightResult[]): FlightResult[] {
  if (base.length === 0) return incoming;
  const seen = new Set(base.map((r) => resultIdentity(r)));
  const merged = [...base];
  for (const row of incoming) {
    const key = resultIdentity(row);
    if (seen.has(key)) continue;
    seen.add(key);
    merged.push(row);
  }
  return merged;
}

function matchesStopFilter(r: FlightResult, filter: StopFilter): boolean {
  switch (filter) {
    case "all":
      return true;
    case "direct":
      return r.stops === 0;
    case "oneStop":
      return r.stops === 1;
    case "twoPlusStops":
      return r.stops >= 2;
    default:
      return true;
  }
}

export default function HomePage() {
  const PAGE_SIZE = 10;
  const [loading, setLoading] = useState<boolean>(false);
  const [results, setResults] = useState<FlightResult[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [tripType, setTripType] = useState<SearchParams["tripType"]>("round-trip");
  const [sortBy, setSortBy] = useState<SortBy>("price");
  const [stopFilter, setStopFilter] = useState<StopFilter>("all");
  const [visibleCount, setVisibleCount] = useState<number>(PAGE_SIZE);
  const [loadingMoreDeals, setLoadingMoreDeals] = useState<boolean>(false);
  const searchSeq = useRef(0);
  const [lastSearchParams, setLastSearchParams] = useState<SearchParams | null>(null);
  const [savedTrips, setSavedTrips] = useState<SavedTrip[]>([]);

  useEffect(() => {
    setSavedTrips(loadSavedTrips());
  }, []);

  const savedFingerprints = useMemo(() => {
    const s = new Set<string>();
    for (const t of savedTrips) {
      s.add(tripFingerprint(t.snapshot, t.searchParams.origin));
    }
    return s;
  }, [savedTrips]);

  const handleSaveResult = useCallback(
    (result: FlightResult) => {
      if (!lastSearchParams) return;
      const trip: SavedTrip = {
        id: crypto.randomUUID(),
        savedAt: new Date().toISOString(),
        searchParams: lastSearchParams,
        snapshot: { ...result },
      };
      setSavedTrips(upsertSavedTrip(trip));
    },
    [lastSearchParams],
  );

  const handleRemoveSaved = useCallback((id: string) => {
    setSavedTrips(removeSavedTrip(id));
  }, []);

  const displayedResults = useMemo(() => {
    if (results == null) return null;
    const filtered = results.filter((r) => matchesStopFilter(r, stopFilter));
    const copy = [...filtered];
    copy.sort((a, b) => {
      if (sortBy === "durationShortest") {
        const ma = a.outboundDurationMinutes ?? Number.POSITIVE_INFINITY;
        const mb = b.outboundDurationMinutes ?? Number.POSITIVE_INFINITY;
        if (ma !== mb) return ma - mb;
        return a.price - b.price;
      }
      return a.price - b.price;
    });
    return copy;
  }, [results, sortBy, stopFilter]);

  useEffect(() => {
    setVisibleCount(PAGE_SIZE);
  }, [results, sortBy, stopFilter]);

  async function handleSearch(params: SearchParams) {
    searchSeq.current += 1;
    const seq = searchSeq.current;
    setLastSearchParams(params);
    setTripType(params.tripType);
    setLoading(true);
    setLoadingMoreDeals(false);
    setResults(null);
    setError(null);

    try {
      const fastRes = await fetch("/api/search", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ...params, searchStage: "fast" }),
      });

      if (!fastRes.ok) {
        const data = await fastRes.json().catch(() => ({}));
        throw new Error(
          (data as { error?: string }).error ??
            `Request failed with status ${fastRes.status}`
        );
      }

      const fastRaw = (await fastRes.json()) as SearchApiResponse;
      const fastData = normalizeSearchResponse(fastRaw);
      if (seq !== searchSeq.current) return;

      setStopFilter("all");
      setSortBy("price");
      setResults(fastData.results);
      setLoading(false);

      const hasMore = Boolean(fastData.meta?.hasMore);
      if (!hasMore) return;

      setLoadingMoreDeals(true);
      try {
        const fullRes = await fetch("/api/search", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ ...params, searchStage: "full" }),
        });
        if (!fullRes.ok) return;
        const fullRaw = (await fullRes.json()) as SearchApiResponse;
        const fullData = normalizeSearchResponse(fullRaw);
        if (seq !== searchSeq.current) return;
        setResults((prev) => mergeUniqueResults(prev ?? [], fullData.results));
      } finally {
        if (seq === searchSeq.current) {
          setLoadingMoreDeals(false);
        }
      }
    } catch (err) {
      if (seq === searchSeq.current) {
        setError(err instanceof Error ? err.message : "Something went wrong.");
      }
    } finally {
      if (seq === searchSeq.current) {
        setLoading(false);
      }
    }
  }

  return (
    <main className="flex min-h-screen flex-col bg-slate-950 text-white">
      <section className="relative isolate flex min-h-[min(88vh,840px)] w-full flex-col">
        <div
          className="absolute inset-0 -z-20 bg-cover bg-center"
          style={{
            backgroundImage:
              "url(https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=2400&q=80)",
          }}
          aria-hidden
        />
        <div
          className="absolute inset-0 -z-10 bg-gradient-to-b from-slate-950/85 via-slate-950/60 to-slate-950"
          aria-hidden
        />
        <div className="relative z-0 flex flex-1 flex-col items-center px-4 pb-16 pt-14 sm:pb-20 sm:pt-20">
          <header className="mb-8 max-w-4xl text-center sm:mb-10">
            <h1 className="text-3xl font-bold tracking-tight text-white drop-shadow-md sm:text-5xl sm:leading-tight">
              Where can I fly?
            </h1>
            <p className="mt-4 text-base leading-relaxed text-white/90 sm:text-lg">
              Find the cheapest flights from anywhere
            </p>
          </header>
          <SearchForm onSearch={handleSearch} />
        </div>
      </section>

      <div className="flex w-full flex-1 flex-col items-center bg-slate-900 px-4 py-10 sm:py-16">
      {loading && (
        <div className="mt-2 flex w-full max-w-[480px] flex-col items-center rounded-2xl border border-indigo-500/30 bg-slate-800/70 px-6 py-7 text-center">
          <div className="relative mb-4">
            <span className="block size-12 rounded-full border-4 border-indigo-400/25" />
            <span className="absolute inset-0 block size-12 animate-spin rounded-full border-4 border-transparent border-t-indigo-300 border-r-cyan-300" />
          </div>
          <p className="text-base font-semibold tracking-wide text-indigo-200">Searching flights...</p>
          <p className="mt-1 text-xs text-slate-400">Comparing fares across providers</p>
        </div>
      )}

      {error != null && (
        <p className="mt-10 w-full max-w-[480px] rounded-xl border border-red-700/60 bg-red-900/30 p-4 text-sm text-red-300">
          {error}
        </p>
      )}

      {results != null && results.length === 0 && (
        <p className="mt-10 text-sm text-slate-400">No results found.</p>
      )}

      {results != null && results.length > 0 && displayedResults != null && (
        <section className="mt-10 w-full max-w-5xl">
          <div className="mb-4 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
            <p className="text-sm text-slate-500">
              {displayedResults.length === results.length
                ? `${results.length} ${results.length === 1 ? "result" : "results"} found`
                : `${displayedResults.length} of ${results.length} results`}
            </p>
            <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:gap-4">
              <label className="flex items-center gap-2 text-sm text-slate-400">
                <span className="whitespace-nowrap">Filter</span>
                <select
                  value={stopFilter}
                  onChange={(e) => setStopFilter(e.target.value as StopFilter)}
                  className="rounded-lg border border-slate-600 bg-slate-900/90 px-3 py-2 text-white outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-500/35"
                  aria-label="Filter by stops"
                >
                  <option value="all">All flights</option>
                  <option value="direct">Non-stop</option>
                  <option value="oneStop">1 stop</option>
                  <option value="twoPlusStops">2+ stops</option>
                </select>
              </label>
              <label className="flex items-center gap-2 text-sm text-slate-400">
                <span className="whitespace-nowrap">Sort by</span>
                <select
                  value={sortBy}
                  onChange={(e) => setSortBy(e.target.value as SortBy)}
                  className="rounded-lg border border-slate-600 bg-slate-900/90 px-3 py-2 text-white outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-500/35"
                  aria-label="Sort results"
                >
                  <option value="price">Price (low to high)</option>
                  <option value="durationShortest">Duration (shortest)</option>
                </select>
              </label>
            </div>
          </div>
          {displayedResults.length === 0 ? (
            <p className="text-sm text-slate-400">
              No flights match this filter. Try another stop count or choose All flights.
            </p>
          ) : (
            <>
              {loadingMoreDeals && (
                <p className="mb-3 text-xs text-slate-500">Finding more flexible deals...</p>
              )}
              <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
                {displayedResults.slice(0, visibleCount).map((r) => (
                  <ResultCard
                    key={`${r.airportCode}-${r.departureDate}-${r.region}`}
                    result={r}
                    tripType={tripType}
                  />
                ))}
              </div>
              {displayedResults.length > visibleCount && (
                <div className="mt-5 flex justify-center">
                  <button
                    type="button"
                    onClick={() => setVisibleCount((n) => n + PAGE_SIZE)}
                    className="rounded-lg border border-slate-600 bg-slate-900/90 px-4 py-2 text-sm font-semibold text-slate-200 transition hover:border-slate-500 hover:bg-slate-800/90"
                  >
                    See more
                  </button>
                </div>
              )}
            </>
          )}
        </section>
      )}
      </div>
    </main>
  );
}
